            "exp": 1700003600,
            "iat": 1700000000,
            "scp": "scope1 scope2"
        }"#;
        let claims: TokenClaims = serde_json::from_str(json).unwrap();
        assert_eq!(claims.scope, Some("scope1 scope2".to_string()));
    }
