    fn malformed_or_wildcard_resource_fails_closed() {
        for resource in [
            "",
            "/mcp",
            "https://",
            "https://*.hajnal.space/mcp",
            "file:///mcp",
        ] {
            assert!(server_config(resource).is_err());
        }
    }
}

