// Validated identity for one authenticated HTTP request.
//
// The auth middleware inserts Identity into HTTP request extensions. rmcp
// passes the current request's Parts through RequestContext, preserving identity
// across spawned SDK tasks without storing credentials in the MCP session.
//
// The task-local accessor is retained for same-task compatibility consumers;
// task-local values are not inherited by spawned tasks and must not be used by
// rmcp tool handlers.

use crate::oauth::AuthStrength;

/// The validated identity for the current request.
#[derive(Clone, Debug, PartialEq)]
pub struct Identity {
    pub user_id: i64,
    pub client_id: String,
    pub scopes: Vec<String>,
    pub auth_strength: AuthStrength,
    pub auth_time: i64,
    pub token_id: String,
}

impl Identity {
    pub fn has_scope(&self, scope: &str) -> bool {
        self.scopes.iter().any(|s| s == scope)
    }
}

impl From<&crate::oauth::TokenValidationResult> for Identity {
    fn from(token: &crate::oauth::TokenValidationResult) -> Self {
        Self {
            user_id: token.user_id,
            client_id: token.oauth_client_id.clone(),
            scopes: token.scopes.clone(),
            auth_strength: token.auth_strength.clone(),
            auth_time: token.auth_time,
            token_id: token.token_id.clone(),
        }
    }
}

tokio::task_local! {
    /// The validated identity for the current request, if authenticated.
    pub static IDENTITY: Option<Identity>;
}

/// Read the validated identity for the current request.
///
/// Returns `None` when no identity has been established for this task (i.e. the
/// request did not pass the auth middleware in this task). rmcp handlers use
/// HTTP request extensions instead.
pub fn current() -> Option<Identity> {
    IDENTITY.try_with(|v| v.clone()).ok().flatten()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn identity_from_token_validation_result() {
        let token = crate::oauth::TokenValidationResult {
            user_id: 42,
            oauth_client_id: "client-1".to_string(),
            scopes: vec!["commoncal.calendar.metadata.read".to_string()],
            auth_strength: AuthStrength::Passkey,
            auth_time: 1_700_000_000,
            expires_at: 1_700_003_600,
            token_id: "token-1".to_string(),
        };
        let identity = Identity::from(&token);
        assert_eq!(identity.user_id, 42);
        assert_eq!(identity.client_id, "client-1");
        assert!(identity.has_scope("commoncal.calendar.metadata.read"));
        assert!(!identity.has_scope("commoncal.event.create"));
        assert_eq!(identity.auth_time, 1_700_000_000);
        assert_eq!(identity.token_id, "token-1");
    }

    #[tokio::test]
    async fn current_returns_none_outside_auth_scope() {
        assert!(current().is_none());
    }

    #[tokio::test]
    async fn current_returns_identity_within_auth_scope() {
        let identity = Identity {
            user_id: 7,
            client_id: "client-7".to_string(),
            scopes: vec![],
            auth_strength: AuthStrength::Mfa,
            auth_time: 0,
            token_id: "token-7".to_string(),
        };
        let observed = IDENTITY
            .scope(Some(identity.clone()), async { current() })
            .await;
        assert_eq!(observed, Some(identity));
        assert!(
            current().is_none(),
            "identity must not escape its request scope"
        );
    }

    #[tokio::test]
    async fn concurrent_tasks_do_not_share_identity() {
        let alice = Identity {
            user_id: 1,
            client_id: "alice".to_string(),
            scopes: vec![],
            auth_strength: AuthStrength::Passkey,
            auth_time: 0,
            token_id: "a".to_string(),
        };
        let bob = Identity {
            user_id: 2,
            client_id: "bob".to_string(),
            scopes: vec![],
            auth_strength: AuthStrength::Passkey,
            auth_time: 0,
            token_id: "b".to_string(),
        };

        let alice_task = tokio::spawn(async move {
            IDENTITY
                .scope(Some(alice.clone()), async {
                    // Yield to force interleaving with the other task.
                    tokio::task::yield_now().await;
                    current().map(|i| i.user_id)
                })
                .await
        });
        let bob_task = tokio::spawn(async move {
            IDENTITY
                .scope(Some(bob.clone()), async {
                    tokio::task::yield_now().await;
                    current().map(|i| i.user_id)
                })
                .await
        });

        let (alice_user, bob_user) = tokio::join!(alice_task, bob_task);
        assert_eq!(
            alice_user.unwrap().unwrap(),
            1,
            "alice must see her own identity"
        );
        assert_eq!(
            bob_user.unwrap().unwrap(),
            2,
            "bob must see his own identity"
        );
    }
}
use mcp_server::{auth, config, db, gateway, mcp_service};

use axum::{
    Router,
    extract::State,
    http::{StatusCode, header::CONTENT_TYPE},
    middleware,
    response::{IntoResponse, Response},
    routing::get,
};
use rmcp::transport::streamable_http_server::{
    session::local::LocalSessionManager, tower::StreamableHttpService,
};
use tower_http::trace::TraceLayer;

use config::Config;
use db::{connect_and_migrate, is_ready};
use gateway::Gateway;
use mcp_service::CommonCalServer;

use tracing_subscriber::{EnvFilter, layer::SubscriberExt, util::SubscriberInitExt};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::registry()
        .with(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")))
        .with(tracing_subscriber::fmt::layer().json())
        .init();

    let config = match Config::from_env() {
        Ok(config) => config,
        Err(errors) => {
            for e in &errors {
                eprintln!("CONFIG ERROR: {}", e);
            }
            std::process::exit(1);
        }
    };
    run(config).await
}

async fn run(config: Config) -> Result<(), Box<dyn std::error::Error>> {
    let db_pool = connect_and_migrate(&config.database_path).await?;

    let gateway = Gateway::new(config.clone(), db_pool.clone())
        .map_err(|e| format!("Gateway initialization failed: {:?}", e))?;

    // Build the rmcp-backed MCP service. The per-request identity is published
    // by the auth middleware into HTTP request extensions; the tool handlers
    // read it at call time, keeping concurrent sessions isolated.
    let server = CommonCalServer::new(
        gateway.internal_client.clone(),
        db_pool.clone(),
        gateway.rate_limiter.clone(),
    );

    let mcp_service: StreamableHttpService<CommonCalServer, LocalSessionManager> =
        StreamableHttpService::new(
            move || Ok(server.clone()),
            LocalSessionManager::default().into(),
            mcp_server::transport::server_config(&config.public_resource_url)?,
        );

    // Auth state for the bearer-token middleware. The protected-resource
    // metadata URL is derived from MCP_PUBLIC_RESOURCE_URL (no loopback).
    let auth_state = auth::AuthState::new(
        config.oauth_issuer.clone(),
        config.public_resource_url.clone(),
    );

    // The MCP endpoint is fully wrapped by bearer-token auth so the first
    // unauthenticated `initialize` receives a standards-compliant 401 challenge.
    let mcp_router =
        Router::new()
            .nest_service("/mcp", mcp_service)
            .layer(middleware::from_fn_with_state(
                auth_state.clone(),
                auth::auth_middleware,
            ));

    let router = Router::new()
        .route("/health/live", get(health_live))
        .route("/health/ready", get(health_ready))
        .route(
            "/.well-known/oauth-protected-resource",
            get(move || {
                let issuer = config.oauth_issuer.clone();
                let dpop_supported = config.dpop_key_path.is_some();
                async move {
                    let meta = crate::config::OauthProtectedResourceMetadata::new(
                        &config.public_resource_url,
                        &issuer,
                        dpop_supported,
                    );
                    (
                        StatusCode::OK,
                        [(CONTENT_TYPE, "application/json")],
                        serde_json::to_string(&meta).unwrap(),
                    )
                        .into_response()
                }
            }),
        )
        .merge(mcp_router)
        .with_state(gateway)
        .layer(
            TraceLayer::new_for_http()
                .make_span_with(|request: &axum::http::Request<_>| {
                    if request.uri().path().starts_with("/health/") {
                        tracing::debug_span!(
                            "http_request",
                            method = %request.method(),
                            path = %request.uri().path()
                        )
                    } else {
                        tracing::info_span!(
                            "http_request",
                            method = %request.method(),
                            path = %request.uri().path()
                        )
                    }
                })
                .on_response(
                    |response: &Response, latency: std::time::Duration, span: &tracing::Span| {
                        let status = response.status().as_u16();
                        let latency_ms = latency.as_millis();
                        if span
                            .metadata()
                            .is_some_and(|m| m.level() == &tracing::Level::DEBUG)
                        {
                            tracing::debug!(
                                status = status,
                                latency_ms = latency_ms,
                                "finished processing request"
                            );
                        } else {
                            tracing::info!(
                                status = status,
                                latency_ms = latency_ms,
                                "finished processing request"
                            );
                        }
                    },
                ),
        );

    let listener = tokio::net::TcpListener::bind(&config.bind_address).await?;

    tracing::info!(
        address = %config.bind_address,
        "mcp-server started"
    );

    axum::serve(listener, router).await?;

    Ok(())
}

async fn health_live() -> impl IntoResponse {
    (StatusCode::OK, "live")
}

async fn health_ready(State(gateway): State<Gateway>) -> impl IntoResponse {
    if is_ready(&gateway.db_pool).await {
        (StatusCode::OK, "ready")
    } else {
        (StatusCode::SERVICE_UNAVAILABLE, "not ready")
    }
}

