        assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
        let www = resp
            .headers()
            .get(header::WWW_AUTHENTICATE)
            .unwrap()
            .to_str()
            .unwrap()
            .to_string();
        assert!(www.starts_with("Bearer "));
        assert!(www.contains(
            "resource_metadata=\"https://mcal.example.com/.well-known/oauth-protected-resource\""
        ));
        assert!(
