    }

    fn remove_env(name: &str) {
        unsafe { env::remove_var(name) };
    }

    fn remove_env_safe(name: &str) -> Option<String> {
        let orig = env::var(name).ok();
        if orig.is_some() {
            unsafe { env::remove_var(name) };
        }
        orig
    }

    #[test]
