        remove_env("APP_ENV");

        let raw = RawConfig {
            app_env: AppEnv::from_env(),
            ..Config::parse_env()
        };

        assert_eq!(raw.app_env, AppEnv::Development);

        if let Some(v) = orig {
            set_env("APP_ENV", &v);
        }
    }

