    (StatusCode::OK, "live")
}

async fn health_ready(State(gateway): State<Gateway>) -> impl IntoResponse {
    if is_ready(&gateway.db_pool).await {
        (StatusCode::OK, "ready")
    } else {
        (StatusCode::SERVICE_UNAVAILABLE, "not ready")
    }
}

